def minimum_fruit_coins(prices):
    n=len(prices);dp=[0]*(n+1)
    for index in range(n-1,-1,-1):dp[index]=prices[index]+min(dp[min(next_index,n)] for next_index in range(index+1,2*index+3))
    return dp[0]

